def stream_rows(resource, transform):
    # Generator function: constructing it, or closing it before the first
    # next(), never runs this body, so neither read_next() nor close() is called.
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit close() (or garbage collection) is not an error: a cleanup
        # failure here propagates out of generator.close().
        resource.close()
        raise
    except BaseException:
        # An iteration or transform error is active: a cleanup failure must not
        # replace it, so the original error is re-raised.
        try:
            resource.close()
        except BaseException:
            pass
        raise
    else:
        # Exhaustion: no error is active, so a cleanup failure propagates.
        resource.close()
EOF
cat > src/consumer.py <<'EOF'
from .service import stream_rows


def _close_preserving_error(stream):
    # Used only while another error is active: a cleanup failure must not
    # replace the original error.
    try:
        stream.close()
    except BaseException:
        pass


def take(resource, transform, limit):
    if limit <= 0:
        # Nothing requested: return without starting the stream.
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    except BaseException:
        _close_preserving_error(stream)
        raise
    # Success path (limit reached or stream exhausted): no error is active, so
    # a cleanup failure propagates. Closing a finished stream is a no-op.
    stream.close()
    return result
EOF
